import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BXn5fPR3.js";const u=JSON.parse('{"title":"Artifacts: Referenced but not shipped on this model","description":"","frontmatter":{},"headers":[],"relativePath":"artifacts/referenced.md","filePath":"artifacts/referenced.md"}'),i={name:"artifacts/referenced.md"};function n(s,e,l,d,c,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="artifacts-referenced-but-not-shipped-on-this-model" tabindex="-1">Artifacts: Referenced but not shipped on this model <a class="header-anchor" href="#artifacts-referenced-but-not-shipped-on-this-model" aria-label="Permalink to &quot;Artifacts: Referenced but not shipped on this model&quot;">​</a></h1><p>Files the software knows about and can use, but which are not present in this model&#39;s firmware image. Some are downloaded on demand when a feature runs (like calibration tones), some belong to other models, and some are created at runtime rather than shipped. Documented here because the code references them by name.</p><details class="details custom-block"><summary>Technical details</summary><p>Path and filename literals recovered from the binary that resolve to CDN downloads, other-model firmware trees, or runtime-created state rather than files in this squashfs.</p></details><h3 id="complete-ogg" tabindex="-1"><code>complete.ogg</code> <a class="header-anchor" href="#complete-ogg" aria-label="Permalink to &quot;`complete.ogg`&quot;">​</a></h3><p>The &#39;finished&#39; jingle played at the end of a calibration pass so you know the measurement succeeded. Named in the binary, fetched on demand.</p><p><em>Not shipped in this build; documented because other firmware versions and binary string evidence reference it.</em></p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/opt/buzzers/complete.ogg</code></li><li><strong>Category:</strong> referenced</li></ul><p>x-rincon-configmode:sonar-calibrate-complete / sonarcal complete.ogg family.</p></details><h3 id="complete-ht-ogg" tabindex="-1"><code>complete_ht.ogg</code> <a class="header-anchor" href="#complete-ht-ogg" aria-label="Permalink to &quot;`complete_ht.ogg`&quot;">​</a></h3><p>The completion tone for home-theater calibration specifically, the variant used when tuning a soundbar rig with satellites.</p><p><em>Not shipped in this build; documented because other firmware versions and binary string evidence reference it.</em></p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/opt/buzzers/complete_ht.ogg</code></li><li><strong>Category:</strong> referenced</li></ul><p>x-rincon-sonarcal:complete_ht.ogg; home-theater variant of the calibration-complete asset.</p></details><h3 id="leader-ogg" tabindex="-1"><code>leader.ogg</code> <a class="header-anchor" href="#leader-ogg" aria-label="Permalink to &quot;`leader.ogg`&quot;">​</a></h3><p>The tone a group leader plays during the older Sonar room-calibration flow. The firmware references it by name, but it is not stored in this model&#39;s image; it is fetched when calibration runs.</p><p><em>Not shipped in this build; documented because other firmware versions and binary string evidence reference it.</em></p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/opt/buzzers/leader.ogg</code></li><li><strong>Category:</strong> referenced</li></ul><p>Referenced by the x-rincon-sonarcal:leader.ogg URI and the trueplay/sonarcal tone-download machinery; delivered on demand via the ETag-cached tone download path rather than shipped in /opt/buzzers.</p></details><h3 id="testtone-ogg" tabindex="-1"><code>testtone.ogg</code> <a class="header-anchor" href="#testtone-ogg" aria-label="Permalink to &quot;`testtone.ogg`&quot;">​</a></h3><p>The measurement tone used while calibrating a speaker&#39;s sound for the room. Referenced by name in the calibration code but downloaded only when a tuning session actually runs.</p><p><em>Not shipped in this build; documented because other firmware versions and binary string evidence reference it.</em></p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/opt/buzzers/testtone.ogg</code></li><li><strong>Category:</strong> referenced</li></ul><p>x-rincon-sonarcal:testtone.ogg; pulled through the tone_download machinery (etags.txt cache) at calibration time.</p></details><h3 id="trueroom-tone-ogg" tabindex="-1"><code>trueroom_tone.ogg</code> <a class="header-anchor" href="#trueroom-tone-ogg" aria-label="Permalink to &quot;`trueroom_tone.ogg`&quot;">​</a></h3><p>The tone for the trueroom tuning pass, a second-generation room measurement the firmware supports but does not ship as a file.</p><p><em>Not shipped in this build; documented because other firmware versions and binary string evidence reference it.</em></p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/opt/buzzers/trueroom_tone.ogg</code></li><li><strong>Category:</strong> referenced</li></ul><p>x-rincon-sonarcal:trueroom family; downloaded per-session like the other sonarcal assets.</p></details><h3 id="level-mp3" tabindex="-1"><code>level.mp3</code> <a class="header-anchor" href="#level-mp3" aria-label="Permalink to &quot;`level.mp3`&quot;">​</a></h3><p>A test tone that the smaller Play:1 model ships for audio level checks. On the Playbar build this file does not exist; the same menu of sounds is implemented but this asset was left out of this model.</p><p><em>Not shipped in this build; documented because other firmware versions and binary string evidence reference it.</em></p><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>Path in image:</strong> <code>/opt/htdocs/audio/level.mp3</code></li><li><strong>Category:</strong> referenced</li></ul><p>271 KB in the m8/fenway rootfs (documented in the firmware-differences page); absent from the m9 image.</p></details>',27)])])}const p=t(i,[["render",n]]);export{u as __pageData,p as default};
